package io.guestgraph.connector.apaleo.api;

import java.io.IOException;
import java.io.InputStream;
import java.util.Map;
import org.springframework.core.io.ClassPathResource;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RestController;
import org.yaml.snakeyaml.Yaml;

/**
 * Serves the connector's contract at GET /api-docs: the one document under src/main/resources/api,
 * generated by service-conventions/regen-api from the contract the engine repository owns at the
 * commit sources.json names, and held against a fresh generation in CI. Outside the ops token,
 * since the document carries no data.
 */
@RestController
public class ApiDocsController {

  private final Map<String, Object> document;

  public ApiDocsController() {
    try (InputStream in = new ClassPathResource("api/openapi.yaml").getInputStream()) {
      this.document = new Yaml().load(in);
    } catch (IOException e) {
      throw new IllegalStateException("Cannot load api/openapi.yaml", e);
    }
  }

  @GetMapping(value = "/api-docs", produces = "application/json")
  public Map<String, Object> apiDocs() {
    return document;
  }
}
